  end

  it 'getHost returns configured host' do
    _(auth.host).must_equal 'https://api.example.com'
  end

  it 'token fetch error is surfaced not swallowed' do
    # oauth-cc-authheaders-error-swallow: a failed client-credentials token
    # exchange must surface to the caller as a raised error — NOT be
    # swallowed into an empty header map that would send the API request
    # unauthenticated and produce a confusing downstream 401.
    error_client = ConfigurableClientCredentialsClient.new([
      { status: 401, body: { 'error' => 'invalid_client' } }
    ])
    error_auth = PetstoreClient::Auth::OAuth::OAuth2ClientCredentialsAuthenticator.new(
      'https://api.example.com',
      'my_client_id',
      'my_client_secret',
      'https://auth.example.com/token',
      %w[read write]
    )
    error_auth.api_client = error_client

    _(-> { error_auth.auth_headers }).must_raise RuntimeError
  end

  it 'caches token across calls' do
    # The token manager caches the access token until expiry, so two
    # consecutive header requests reuse the same token and issue only a
    # single token request to the endpoint.
    caching_client = ConfigurableClientCredentialsClient.new([
      { status: 200, body: { 'access_token' => 'cached_cc_token', 'expires_in' => 3600 } }
    ])
    caching_auth = PetstoreClient::Auth::OAuth::OAuth2ClientCredentialsAuthenticator.new(
      'https://api.example.com',
      'my_client_id',
      'my_client_secret',
      'https://auth.example.com/token',
      %w[read write]
    )
    caching_auth.api_client = caching_client

    headers1 = caching_auth.auth_headers
    headers2 = caching_auth.auth_headers

    _(headers1['Authorization']).must_equal 'Bearer cached_cc_token'
    _(headers2['Authorization']).must_equal 'Bearer cached_cc_token'
    _(caching_client.call_count).must_equal 1
  end

  it 'basic auth url-encodes client id and secret' do
    # Gap R: RFC 6749 §2.3.1 — when using client_secret_basic, both
    # client_id and client_secret MUST be application/x-www-form-
    # urlencoded BEFORE being joined with ':' and base64-encoded.
    basic_client = FakeClientCredentialsClient.new
    basic_auth = PetstoreClient::Auth::OAuth::OAuth2ClientCredentialsAuthenticator.new(
      'https://api.example.com',
      'id+with/special',
      'secret&with=stuff',
      'https://auth.example.com/token',
      %w[read],
      client_auth_method: PetstoreClient::Auth::OAuth::ClientAuthMethod::BASIC
    )
    basic_auth.api_client = basic_client

    basic_auth.auth_headers

    auth_header = basic_client.last_headers['Authorization']
    _(auth_header).wont_be_nil
    _(auth_header.start_with?('Basic ')).must_equal true
    decoded = Base64.strict_decode64(auth_header.sub(/\ABasic /, ''))
    _(decoded).must_equal 'id%2Bwith%2Fspecial:secret%26with%3Dstuff'
  end

  it 'masks the client secret in inspect' do
    # client-secret-leak-in-default-repr: the default Object#inspect dumps
    # every instance variable, leaking @client_secret. The overridden
    # inspect must mask it.
    secret_auth = PetstoreClient::Auth::OAuth::OAuth2ClientCredentialsAuthenticator.new(
      'https://api.example.com',
      'my_client_id',
      'super_secret_value',
      'https://auth.example.com/token',
      %w[read]
